CREATE DEFINER=`root`@`localhost` PROCEDURE `eliminar_reservas_post_fecha`(IN fecha_limite VARCHAR(10))
BEGIN
    DECLARE fecha DATE;
    SET fecha = STR_TO_DATE(fecha_limite, '%d/%m/%Y');
    
	-- Eliminar pagos
    DELETE FROM pago WHERE pago_fechahora >= fecha;

    -- Eliminar detalles de factura
    DELETE FROM facturadetalle
    WHERE rela_factura IN (
        SELECT id_factura FROM factura
        WHERE rela_reserva IN (
            SELECT id_reserva FROM reserva WHERE reserva_fhinicio >= fecha
        )
    );

    -- Eliminar facturas
    DELETE FROM factura
    WHERE rela_reserva IN (
        SELECT id_reserva FROM reserva WHERE reserva_fhinicio >= fecha
    );

    -- Eliminar relación huesped-reserva
    DELETE FROM huesped_reserva
    WHERE rela_reserva IN (
        SELECT id_reserva FROM reserva WHERE reserva_fhinicio >= fecha
    );

    -- Eliminar consumos
    DELETE FROM consumo
    WHERE rela_reserva IN (
        SELECT id_reserva FROM reserva WHERE reserva_fhinicio >= fecha
    );
    
    -- Eliminar revisiones
    DELETE FROM revision
    WHERE rela_reserva IN (
        SELECT id_reserva FROM reserva WHERE reserva_fhinicio >= fecha
    );

    -- Eliminar reservas
    DELETE FROM reserva WHERE reserva_fhinicio >= fecha;
END ;;
DELIMITER ;
