CREATE DEFINER=`root`@`localhost` PROCEDURE `eliminar_usuario_por_nombre`(IN nombre_usuario VARCHAR(100))
BEGIN
    DECLARE v_id_usuario INT;
    DECLARE v_rela_persona INT;

    -- Obtener los valores necesarios
    SELECT id_usuario, rela_persona
    INTO v_id_usuario, v_rela_persona
    FROM proyecto_cabania.usuario
    WHERE usuario_nombre = nombre_usuario;

    -- Eliminar registros relacionados
    DELETE FROM proyecto_cabania.contacto WHERE rela_persona = v_rela_persona;
    DELETE FROM proyecto_cabania.huesped WHERE rela_persona = v_rela_persona;
    DELETE FROM proyecto_cabania.usuario WHERE id_usuario = v_id_usuario;
    DELETE FROM proyecto_cabania.persona WHERE id_persona = v_rela_persona;
END ;;
DELIMITER ;
